  async function start() { installPresentation();installProcessingAudioDiagnostics();installPTT();installSessionControl(); tick(); setInterval(tick,1000); await Promise.allSettled([refreshSnapshot(),refreshEvents()]); connectEvents(); setInterval(refreshSnapshot,SNAPSHOT_INTERVAL_MS); }
  start();
